{
  "name": "通用 USB-FPGA 通信组件",
  "name_en": "Generic USB-to-FPGA Communication Component",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，用于扫描 USB 设备、连接 USB 转 UART 桥接器，并与 FPGA 板卡进行串口数据收发。它主要供上层实验软件用于发现设备、发送寄存器设置命令和轮询读取数据。",
  "description_en": "A non-physical software communication component that scans USB devices, connects through a USB-to-UART bridge, and exchanges serial data with FPGA boards. It is used by higher-level lab software to discover devices, send register-setting commands, and poll for returned data.",
  "tag_hints": [
    "USB-to-UART communication",
    "FPGA interface",
    "device discovery",
    "serial polling",
    "register write commands",
    "ctypes DLL access",
    "lab software helper"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化该非物理通信组件并启动 USB 连接检查流程。",
      "description_en": "Initialize this non-physical communication component and start checking for USB connections."
    },
    {
      "action_name": "auto-checkConnections",
      "description": "轮询 USB 连接，扫描可用的 FPGA 相关设备并更新发现列表。",
      "description_en": "Poll USB connections, scan for available FPGA-related devices, and update the discovered-device list."
    },
    {
      "action_name": "auto-connectUsb",
      "description": "连接选定的 USB 转 UART 设备，并配置串口参数以与 FPGA 通信。",
      "description_en": "Connect to the selected USB-to-UART device and configure UART parameters for communication with the FPGA."
    },
    {
      "action_name": "auto-set",
      "description": "向 FPGA 寄存器发送设置命令并写入指定值。",
      "description_en": "Send a set command to an FPGA register and write the specified value."
    },
    {
      "action_name": "auto-poll",
      "description": "发送轮询请求，以启动或继续从 FPGA 获取连续返回数据。",
      "description_en": "Send a poll request to start or continue receiving streaming response data from the FPGA."
    },
    {
      "action_name": "auto-receive",
      "description": "通过 USB-UART 接收 FPGA 返回的数据，并在完整消息到达时通知上层软件。",
      "description_en": "Receive data returned by the FPGA over USB-UART and notify higher-level software when a complete message arrives."
    },
    {
      "action_name": "auto-restartTimer",
      "description": "重启接收定时器，以持续周期性检查接收缓冲区。",
      "description_en": "Restart the receive timer to continue periodically checking the receive buffer."
    },
    {
      "action_name": "auto-closing",
      "description": "在软件关闭时停止定时器并断开 USB 通信。",
      "description_en": "Stop timers and disconnect USB communication when the software is closing."
    }
  ]
}

